                <form method="get">
                    <input class="search" name="search" value="<?= htmlspecialchars($search) ?>" placeholder="Search topics...">
                </form>
            </div>

            <?php
            $visibleTopics = array_filter($topics, function($topic) use ($search) {
                if ($search === '') return true;
                $text = strtolower(
                    ($topic['course_code'] ?? '') . ' ' .
                    ($topic['course_name'] ?? '') . ' ' .
                    ($topic['topic_number'] ?? '') . ' ' .
                    ($topic['topic_title'] ?? '') . ' ' .
                    ($topic['description'] ?? '')
                );
                return strpos($text, strtolower($search)) !== false;
            });
            ?>

            <?php if ($visibleTopics): ?>
                <div class="table-wrap">
                    <table>
                        <thead>
                        <tr>
                            <th>Course</th>
                            <th>No.</th>
                            <th>Topic Title</th>
                            <th>Description</th>
                            <th>Hours</th>
                            <th>Action</th>
                        </tr>
                        </thead>
                        <tbody>
                        <?php foreach ($visibleTopics as $topic): ?>
