                                <td>
                                    <strong><?= htmlspecialchars($topic['course_code']) ?></strong><br>
                                    <small><?= htmlspecialchars($topic['course_name']) ?></small>
                                </td>
                                <td><span class="badge"><?= htmlspecialchars($topic['topic_number']) ?></span></td>
                                <td><strong><?= htmlspecialchars($topic['topic_title']) ?></strong></td>
                                <td><?= htmlspecialchars($topic['description'] ?: '—') ?></td>
